instruction:
Write Jest unit tests for this JavaScript function.

function sum(a, b) {
  return a + b;
}

output:
const { sum } = require('./sum');

describe('sum', () => {
  test('adds two positive numbers', () => {
    expect(sum(2, 3)).toBe(5);
  });

  test('adds negative numbers', () => {
    expect(sum(-1, -1)).toBe(-2);
  });

  test('returns zero for zeros', () => {
    expect(sum(0, 0)).toBe(0);
  });
});

instruction:
Write Jest unit tests for a capitalize helper that uppercases the first letter of a string.

function capitalize(str) {
  if (!str) return '';
  return str[0].toUpperCase() + str.slice(1).toLowerCase();
}

output:
const { capitalize } = require('./capitalize');

describe('capitalize', () => {
  test('capitalizes a lowercase word', () => {
    expect(capitalize('hello')).toBe('Hello');
  });

  test('lowercases the remaining letters', () => {
    expect(capitalize('hELLO')).toBe('Hello');
  });

  test('returns empty string for empty input', () => {
    expect(capitalize('')).toBe('');
  });
});

