Write Jest unit tests for a fizzbuzz function that returns strings for multiples of 3, 5 and 15.

function fizzbuzz(n) {
  if (n % 15 === 0) return 'FizzBuzz';
  if (n % 3 === 0) return 'Fizz';
  if (n % 5 === 0) return 'Buzz';
  return String(n);
}

output:
const { fizzbuzz } = require('./fizzbuzz');

describe('fizzbuzz', () => {
  test.each([
    [1, '1'],
    [3, 'Fizz'],
    [5, 'Buzz'],
    [15, 'FizzBuzz'],
  ])('fizzbuzz(%i) === %s', (n, expected) => {
    expect(fizzbuzz(n)).toBe(expected);
  });
});

