instruction:
Write a Jest test that mocks the global fetch for an async getUser function and asserts the parsed result.

async function getUser(id) {
  const resp = await fetch(`/api/users/${id}`);
  if (!resp.ok) throw new Error('not found');
  return resp.json();
}

output:
const { getUser } = require('./getUser');

describe('getUser', () => {
  beforeEach(() => {
    global.fetch = jest.fn();
  });

  test('returns parsed user json', async () => {
    fetch.mockResolvedValue({
      ok: true,
      json: async () => ({ id: 1, name: 'Ann' }),
    });
    await expect(getUser(1)).resolves.toEqual({ id: 1, name: 'Ann' });
    expect(fetch).toHaveBeenCalledWith('/api/users/1');
  });

  test('rejects when response is not ok', async () => {
    fetch.mockResolvedValue({ ok: false });
    await expect(getUser(9)).rejects.toThrow('not found');
  });
});

