Write a Jest test for a delay(ms) promise helper, verifying it resolves after approximately the given time (use fake timers).

function delay(ms) {
  return new Promise((resolve) => setTimeout(resolve, ms));
}

output:
const { delay } = require('./delay');

describe('delay', () => {
  beforeEach(() => {
    jest.useFakeTimers();
  });
  afterEach(() => {
    jest.useRealTimers();
  });

  test('resolves after the specified delay', async () => {
    const promise = delay(1000);
    jest.advanceTimersByTime(1000);
    await expect(promise).resolves.toBeUndefined();
  });
});

instruction:
Write Jest unit tests for a TaskQueue class with add and size, ensuring tasks are stored in order.

class TaskQueue {
  constructor() { this.tasks = []; }
  add(task) { this.tasks.push(task); return this.tasks.length; }
  size() { return this.tasks.length; }
  next() { return this.tasks.shift(); }
}

output:
const TaskQueue = require('./taskQueue');

describe('TaskQueue', () => {
  test('add increases size and stores order', () => {
    const queue = new TaskQueue();
    expect(queue.add('a')).toBe(1);
    expect(queue.add('b')).toBe(2);
    expect(queue.size()).toBe(2);
  });

  test('next removes the first task', () => {
    const queue = new TaskQueue();
    queue.add('first');
    queue.add('second');
    expect(queue.next()).toBe('first');
    expect(queue.size()).toBe(1);
  });
});

