Write Jest unit tests asserting custom errors from a validateEmail function using toThrow with the error class and message.

class ValidationError extends Error {}

function validateEmail(email) {
  if (!email || !email.includes('@')) {
    throw new ValidationError('invalid email');
  }
  return email.toLowerCase();
}

output:
const { validateEmail, ValidationError } = require('./validateEmail');

describe('validateEmail', () => {
  test('returns lowercased email when valid', () => {
    expect(validateEmail('Ann@Example.com')).toBe('ann@example.com');
  });

  test('throws ValidationError with message', () => {
    expect(() => validateEmail('nope')).toThrow(ValidationError);
    expect(() => validateEmail('nope')).toThrow('invalid email');
  });

  test('throws on empty email', () => {
    expect(() => validateEmail('')).toThrow(ValidationError);
  });
});

