Write a Jest test using spies to assert a notifier.send was called with the exact arguments for a publish function.

function publish(events, notifier) {
  for (const event of events) {
    notifier.send(event.type, event.payload);
  }
  return events.length;
}

output:
const { publish } = require('./publish');

describe('publish', () => {
  test('notifier.send called once per event', () => {
    const notifier = { send: jest.fn() };
    const events = [
      { type: 'order', payload: { id: 1 } },
      { type: 'ship', payload: { id: 1 } },
    ];
    expect(publish(events, notifier)).toBe(2);
    expect(notifier.send).toHaveBeenCalledTimes(2);
    expect(notifier.send).toHaveBeenCalledWith('order', { id: 1 });
    expect(notifier.send).toHaveBeenNthCalledWith(2, 'ship', { id: 1 });
  });
});

