describe('NotesApp', () => {
  let app;

  beforeEach(() => {
    app = new NotesApp();
    app.add('first');
    app.add('second');
  });

  test('list returns added notes', () => {
    expect(app.list()).toHaveLength(2);
    expect(app.list()[0]).toEqual({ id: 1, text: 'first' });
  });

  test('fresh fixture for each test', () => {
    expect(app.list()).toHaveLength(2);
    app.add('third');
    expect(app.list()).toHaveLength(3);
  });
});

