Write Jest unit tests for a pipe function that composes unary functions left to right.

function pipe(...fns) {
  return (input) => fns.reduce((acc, fn) => fn(acc), input);
}

output:
const { pipe } = require('./pipe');

describe('pipe', () => {
  const double = (x) => x * 2;
  const increment = (x) => x + 1;
  const toStr = (x) => String(x);

  test('applies functions left to right', () => {
    expect(pipe(double, increment)(3)).toBe(7);
  });

  test('works with three functions', () => {
    expect(pipe(double, increment, toStr)(5)).toBe('11');
  });

  test('identity when no functions given', () => {
    expect(pipe()('raw')).toBe('raw');
  });
});

