Write a Jest test that mocks localStorage for a saveTheme function and asserts setItem was called with the right keys.

function saveTheme(theme) {
  localStorage.setItem('theme', theme);
  localStorage.setItem('themeSavedAt', String(Date.now()));
  return true;
}

output:
const { saveTheme } = require('./theme');

describe('saveTheme', () => {
  beforeEach(() => {
    const store = {};
    global.localStorage = {
      getItem: jest.fn((k) => store[k] ?? null),
      setItem: jest.fn((k, v) => { store[k] = String(v); }),
      removeItem: jest.fn((k) => { delete store[k]; }),
    };
  });

  test('persists theme keys to localStorage', () => {
    expect(saveTheme('dark')).toBe(true);
    expect(localStorage.setItem).toHaveBeenCalledWith('theme', 'dark');
    expect(localStorage.setItem).toHaveBeenCalledWith('themeSavedAt', expect.any(String));
  });
});

instruction:
Write Vitest tests using vi.fn for a payments module that calls a stripe-like client.

export async function charge(client, amount) {
  const result = await client.charges.create({ amount, currency: 'usd' });
  return result.id;
}

output:
import { describe, test, expect, vi, beforeEach } from 'vitest';
import { charge } from './payments';

describe('charge', () => {
  let client;

  beforeEach(() => {
    client = { charges: { create: vi.fn() } };
  });

  test('returns the created charge id', async () => {
    client.charges.create.mockResolvedValue({ id: 'ch_123' });
    await expect(charge(client, 500)).resolves.toBe('ch_123');
    expect(client.charges.create).toHaveBeenCalledWith({ amount: 500, currency: 'usd' });
  });

  test('propagates client failures', async () => {
    client.charges.create.mockRejectedValue(new Error('card declined'));
    await expect(charge(client, 500)).rejects.toThrow('card declined');
  });
});
